"""Rebuild a finite evidence-audit report; no catalogue changes."""
import json,hashlib,collections,subprocess
from pathlib import Path
ROOT=Path(__file__).resolve().parents[3]
doc=json.loads((ROOT/'data/research/population-184-evidence-audit.json').read_text(encoding='utf-8'))
records=doc['records'];estimates=[e for r in records for e in r['estimates']]
def clean(x):return str(x).replace('|','/').replace('\n',' ')
def number(e):
    if e.get('reportedBound'):return str(e['reportedBound']['operator'])+' '+str(e['reportedBound']['value'])
    if e.get('reportedNumericRange'):
        r=e['reportedNumericRange'];return f"{r['min']}–{r['max']} ({r['qualifier']})"
    if e['value'] is not None:return '≈'+str(e['value'])
    result=f"{e['min']}–{e['max']}"
    if e.get('sourceReportedCentralEstimate') is not None:result+='; авторская точка ≈'+str(e['sourceReportedCentralEstimate'])
    return result
def year(e):
    if e['year'] is not None:return str(e['year'])
    p=e.get('observationPeriod')
    if p:
        if p.get('verbatim'):return p['verbatim']
        return f"{p['startYear']}–{p['endYear']}"
    if e.get('statisticalReferenceYear'):return 'полевой неизвестен; отчётный '+str(e['statisticalReferenceYear'])
    if e.get('assessmentYear'):return 'полевой неизвестен; evaluation '+str(e['assessmentYear'])
    return 'не установлен'
